typedef struct node
{
    int number;
    struct node *next;
}
node;

// تألیفی
node *n = malloc(sizeof(node));
if (n != NULL)
{
    (*n).number = 1;   // بلندتر
    n->number = 1;     // همان، کوتاه‌تر
    n->next = NULL;
}

